#!/usr/bin/env python3
"""simcompare 단일 파일 실행기 (자동 생성: scripts/build_single_file.py). 소스 해시 db4b6ba931179f632d1f7474bfcf4b8ab9d3cf9438a4b6000fbd842d589e4107.
서버 wrapper가 명령줄 인자를 넘기지 못할 때 쓴다. 아래 EDIT 블록만 고치고 이 파일을 그대로 실행한다."""
# 1m회차(선택, 다제품·모델별 리포트): 모델(제3 제품) hotspot import. 1회차와 같은 명령을 모델마다 한 번 실행한다.
# 모델 자산은 사용자가 나중에 모델별 폴더로 준다. 폴더 규칙은 data/models/<product_id>/ 이다(manifest.json + pairs.csv 복사,
# 3m회차 뒤 review_assets.json·electrode_asset_import_record.json·assets/ 도 이 폴더로 복사한다). 이 폴더가 없으면 그 모델은 assets_pending 이다
# (5m회차에서 후보는 보이지만 accept 해도 deferred.json 에 남고 종료 코드 3).
# --root는 모델 hotspot root, --expected-cases-from-roots는 target(QA4_T00) root, --out은 아직 없는 data/models/<모델>이다. 모델 id QA4_C00는 예시다.
# 끝나면 pairs.csv를 data/models/<모델>/ 안에 복사한다. 모델 키(product_id)는 models.yaml(configs/etx/models.example.yaml)의 모델 키와 같아야 한다.
# 모델이 둘 이상이면 모델마다 JOBS 줄을 늘린다. 1~7회차의 reference·target 흐름은 바뀌지 않는다.
# ============================== EDIT BELOW: 이 블록만 고치세요 ==============================
# 각 작업은 `python -m simcompare <명령> <인자...>`와 같다. 명령 이름은 import-hotspots, validate-data, compare,
# electrode-map, import-electrode-assets, export-review-rois, candidates-change, candidates, confirm-pairs, compare-windows, report 등이다.
# 인자는 명령줄에서 쓰던 그대로 문자열 리스트로 적는다. 상대 경로는 BASE_DIR 기준이다(아래). wrapper가 이 파일을 다른 곳에
# 복사해 실행하면 "이 .py가 있는 폴더"가 달라지므로, 상대 경로를 쓸 때는 BASE_DIR를 절대 경로로 적는 것이 안전하다.
# 작업은 위에서부터 차례로 실행된다. 종료 코드 0(완료)과 3(부분 결과)은 다음 작업으로 넘어가고, 그 밖의 코드는 멈춘다.
JOBS = [
    # 모델 QA4_C00 (예시). --out은 아직 없는 새 경로. 끝나면 pairs.csv를 이 폴더에 복사
    ('import-hotspots', [
        '--root', 'data/input/hotspot/QA4_C00',
        '--expected-cases-from-roots', 'data/input/hotspot/QA4_T00',
        '--out', 'data/models/QA4_C00',
    ]),
]
LOG_FILE = 'runs/simcompare_1m_import_models.log'   # stdout/stderr를 이 파일에도 남긴다. 필요 없으면 None
WORK_DIR = None                               # 패키지를 풀 폴더. None이면 이 파일 옆, 쓸 수 없으면 임시 폴더
BASE_DIR = None                               # JOBS·LOG_FILE·WORK_DIR의 상대 경로 기준 폴더(절대 경로). None이면 이 .py가 있는 폴더
# ============================== EDIT ABOVE ==============================================

